    val displayName: String,
    val email: String,
    val externalRef: String? = null,
    val status: String,
    val commission: Amounts,
    val referrals: List<GraphReferral>,
) {
    fun toJson(): JsonValue = JsonValue.Obj(buildMap {
        put("partnerId", JsonValue.Str(this@GraphPartner.partnerId))
        put("displayName", JsonValue.Str(this@GraphPartner.displayName))
        put("email", JsonValue.Str(this@GraphPartner.email))
        put("externalRef", (this@GraphPartner.externalRef?.let { JsonValue.Str(it) } ?: JsonValue.Null))
        put("status", JsonValue.Str(this@GraphPartner.status))
        put("commission", JsonValue.Arr(this@GraphPartner.commission.map { it.toJson() }))
        put("referrals", JsonValue.Arr(this@GraphPartner.referrals.map { it.toJson() }))
    })

    companion object {
        fun fromJson(json: JsonValue): GraphPartner {
            val o = json.obj()
            return GraphPartner(
                partnerId = o.field("partnerId").string(),
                displayName = o.field("displayName").string(),
                email = o.field("email").string(),
                externalRef = o.field("externalRef").orNull()?.let { it.string() },
                status = o.field("status").string(),
                commission = o.field("commission").array().map { AmountsValueItem.fromJson(it) },
                referrals = o.field("referrals").array().map { GraphReferral.fromJson(it) },
            )
        }
    }
}

