data class CreatorProfile(
    val accountId: String,
    val name: String? = null,
    val email: String? = null,
    val published: Boolean,
    val headline: String,
    val bio: String,
    val categories: List<String>,
    val languages: List<String>,
    val country: String,
    val channels: List<GetOpenapiJsonResponse>,
    val website: String,
    val minAudience: Long,
    val acceptsInvites: Boolean,
    val audience: GetOpenapiJsonResponse,
    val engagementBps: Long,
    val stats: CreatorProfileStats,
    val invited: Boolean? = null,
) {
    fun toJson(): JsonValue = JsonValue.Obj(buildMap {
        put("accountId", JsonValue.Str(this@CreatorProfile.accountId))
        put("name", (this@CreatorProfile.name?.let { JsonValue.Str(it) } ?: JsonValue.Null))
        if (this@CreatorProfile.email != null) put("email", (this@CreatorProfile.email?.let { JsonValue.Str(it) } ?: JsonValue.Null))
        put("published", JsonValue.Bool(this@CreatorProfile.published))
        put("headline", JsonValue.Str(this@CreatorProfile.headline))
        put("bio", JsonValue.Str(this@CreatorProfile.bio))
        put("categories", JsonValue.Arr(this@CreatorProfile.categories.map { JsonValue.Str(it) }))
        put("languages", JsonValue.Arr(this@CreatorProfile.languages.map { JsonValue.Str(it) }))
        put("country", JsonValue.Str(this@CreatorProfile.country))
        put("channels", JsonValue.Arr(this@CreatorProfile.channels.map { JsonValue.Obj(it.mapValues { it.value }) }))
        put("website", JsonValue.Str(this@CreatorProfile.website))
        put("minAudience", JsonValue.Num(this@CreatorProfile.minAudience.toDouble()))
        put("acceptsInvites", JsonValue.Bool(this@CreatorProfile.acceptsInvites))
        put("audience", JsonValue.Obj(this@CreatorProfile.audience.mapValues { it.value }))
        put("engagementBps", JsonValue.Num(this@CreatorProfile.engagementBps.toDouble()))
        put("stats", this@CreatorProfile.stats.toJson())
        if (this@CreatorProfile.invited != null) put("invited", (this@CreatorProfile.invited?.let { JsonValue.Bool(it) } ?: JsonValue.Null))
    })

    companion object {
        fun fromJson(json: JsonValue): CreatorProfile {
            val o = json.obj()
            return CreatorProfile(
                accountId = o.field("accountId").string(),
                name = o.field("name").orNull()?.let { it.string() },
                email = o["email"]?.orNull()?.let { it.string() },
                published = o.field("published").bool(),
                headline = o.field("headline").string(),
                bio = o.field("bio").string(),
                categories = o.field("categories").array().map { it.string() },
                languages = o.field("languages").array().map { it.string() },
                country = o.field("country").string(),
                channels = o.field("channels").array().map { it.obj().mapValues { it.value } },
                website = o.field("website").string(),
                minAudience = o.field("minAudience").long(),
                acceptsInvites = o.field("acceptsInvites").bool(),
                audience = o.field("audience").obj().mapValues { it.value },
                engagementBps = o.field("engagementBps").long(),
                stats = CreatorProfileStats.fromJson(o.field("stats")),
                invited = o["invited"]?.orNull()?.let { it.bool() },
            )
        }
    }
}

